    """规约：序列中的整数位于 range(a, b) 内，即 a <= x < b。"""
    a, b = 2, 7
    result = subsequences(a=a, b=b, k=3)
    for seq in result:
        for x in seq:
            assert a <= x < b


def test_subsequences_all_elements_are_ints():
