        for x in seq:
            assert isinstance(x, int)


def test_subsequences_count_matches_combinations():
    """规约：所有长度为 k 的递增序列数量应等于 C(b-a, k)。"""
    from math import comb

    a, b, k = 1, 6, 3
    result = subsequences(a=a, b=b, k=k)
    assert len(result) == comb(b - a, k)


def test_subsequences_no_duplicates():
    """规约：返回的是所有序列的集合，不应有重复。"""
    result = subsequences(a=1, b=6, k=3)
    as_tuples = [tuple(seq) for seq in result]
    assert len(as_tuples) == len(set(as_tuples))


def test_subsequences_k_equals_one():
    """规约：k=1 时返回所有单元素序列，即 [[a], [a+1], ..., [b-1]]。"""
    a, b = 1, 5
    result = subsequences(a=a, b=b, k=1)
    assert result == [[x] for x in range(a, b)]


def test_subsequences_k_equals_range_size():
    """规约：k 等于 b-a 时只有唯一序列 [a, a+1, ..., b-1]。"""
    a, b = 1, 5
    result = subsequences(a=a, b=b, k=b - a)
    assert result == [list(range(a, b))]


def test_subsequences_k_greater_than_range_size_returns_empty():
    """规约：k 大于 b-a 时不存在长度为 k 的递增序列，应为空列表。"""
    result = subsequences(a=1, b=4, k=5)
    assert result == []


def test_subsequences_k_zero_returns_empty_sequence():
